INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Mệnh',N'chinh_tinh_cung',N'Tử Vi tại Mệnh',N'Mệnh',N'{"co": "Tử Vi"}',N'Bạn có phong thái uy nghi, tự trọng và tố chất của người đứng đầu.',N'Bạn dễ tự cao và hay thấy mình đơn độc, nên coi chừng chuyện ham hư danh.',2,N'da_viet_lai_giong_nguoi_doc');
INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Phụ Mẫu',N'chinh_tinh_cung',N'Tử Vi tại Phụ Mẫu',N'Phụ Mẫu',N'{"co": "Tử Vi"}',N'Cha mẹ bạn có vị thế và che chở được cho bạn.',N'Cha mẹ bạn khá nghiêm, nên hai bên khó gần gũi.',1,N'da_viet_lai_giong_nguoi_doc');
INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Phúc Đức',N'chinh_tinh_cung',N'Tử Vi tại Phúc Đức',N'Phúc Đức',N'{"co": "Tử Vi"}',N'Dòng họ có người thành đạt và bạn được hưởng phúc dày.',N'Bạn có phúc nhưng cũng phải gánh trách nhiệm với họ hàng.',2,N'da_viet_lai_giong_nguoi_doc');
INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Điền Trạch',N'chinh_tinh_cung',N'Tử Vi tại Điền Trạch',N'Điền Trạch',N'{"co": "Tử Vi"}',N'Nhà cửa của bạn thường khang trang, đàng hoàng.',N'Bạn có nhà cửa nhưng việc giữ gìn khá tốn kém.',1,N'da_viet_lai_giong_nguoi_doc');
INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Quan Lộc',N'chinh_tinh_cung',N'Tử Vi tại Quan Lộc',N'Quan Lộc',N'{"co": "Tử Vi"}',N'Bạn hợp làm quản lý hoặc ở vị trí đứng đầu.',N'Bạn muốn làm chủ nhưng hay thiếu người đỡ đầu hoặc cộng sự ăn ý.',2,N'da_viet_lai_giong_nguoi_doc');
INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Nô Bộc',N'chinh_tinh_cung',N'Tử Vi tại Nô Bộc',N'Nô Bộc',N'{"co": "Tử Vi"}',N'Bạn bè, cấp dưới của bạn có thế lực và nhiều người đáng nể.',N'Cấp dưới dễ lấn lướt, nên bạn cần giữ ranh giới rõ ràng.',0,N'da_viet_lai_giong_nguoi_doc');
